package com.mahesh.empleave.employee;import com.mahesh.empleave.audit.*;import com.mahesh.empleave.user.*;import jakarta.validation.constraints.*;import lombok.*;import org.springframework.security.core.*;import org.springframework.transaction.annotation.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/employees/me") @RequiredArgsConstructor public class ProfileController{private final UserRepository users;private final AuditService audit;record Update(@NotBlank @Size(max=160) String fullName){}@PutMapping @Transactional EmployeeProfile update(Authentication a,@RequestBody @jakarta.validation.Valid Update x){var u=users.findByEmail(a.getName()).orElseThrow();u.updateOwnProfile(x.fullName());audit.log(u,"PROFILE_UPDATED","EMPLOYEE",u.getId());return EmployeeProfile.from(u);}}
